using System.Collections.ObjectModel; // ❗ See on vajalik ObservableCollectioni jaoks

namespace naidis_TARpe24SavvaSmirnyagin;



public partial class CarouselPage : ContentPage

{

    public class CarouselItem

    {

        public string Title { get; set; }

        public string ImageUrl { get; set; }
        public string Description { get; set; }

    }

    private CarouselView carouselView;

    // List asendati ObservableCollectioniga

    private ObservableCollection<CarouselItem> items;

    private int position = 0;

    public CarouselPage()

    {

        Title = "Karussell - Dünaamiline lisamine";



        // Initsialiseerime ObservableCollectioni

        items = new ObservableCollection<CarouselItem>

        {

            new CarouselItem
            {
                Title = "Pasta Carbonara", 
                ImageUrl = "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTd-hUs4eaWS4PW-dmn7QUdPFwpKtrib6myL6Wwxc3rwGLBCj4Zag7wE22V2eBa-C-s0KcTYWffMqSghStLWmX1a3MStFF-1dhhd15P2tst&s=10",
                Description = "Klassikaline Rooma pastaroog"
            },

            new CarouselItem 
            { 
                Title = "Pizza Margherita", 
                ImageUrl = "data:image/jpeg;base64,",
                Description = "Lihtne ja maitsev"
            },

            new CarouselItem 
            { 
                Title = "Tiramisu", 
                ImageUrl = "data:image/jpeg;base64,",
                Description = "Populaarne kohvimaitseline magustoit"
            },

            new CarouselItem 
            { 
                Title = "Risotto alla Milanese", 
                ImageUrl = "data:image/jpeg;base64,",
                Description = "Kreemine safraniriis"
            },

            new CarouselItem 
            { 
                Title = "Lasagne",
                ImageUrl = "data:image/jpeg;base64,",
                Description = "Kihiline pasta liha ja juustuga"
            },

        };



        // Karusselli loomine (kood on sama, mis eelmises versioonis)

        carouselView = new CarouselView

        {

            ItemsSource = items,

            HeightRequest = 350,

            PeekAreaInsets = new Thickness(40, 0, 40, 0),



            ItemTemplate = new DataTemplate(() =>

            {

                var frame = new Frame

                {

                    CornerRadius = 15,

                    HasShadow = true,

                    Padding = 0,

                    Margin = new Thickness(5),

                    BackgroundColor = Colors.Black

                };



                var grid = new Grid();

                var image = new Image { Aspect = Aspect.AspectFill };

                image.SetBinding(Image.SourceProperty, "ImageUrl");



                var gradient = new BoxView

                {

                    Background = new LinearGradientBrush

                    {

                        StartPoint = new Point(0, 1),

                        EndPoint = new Point(0, 0),

                        GradientStops = new GradientStopCollection

                        {

                            new GradientStop(Colors.Black.WithAlpha(0.7f), 0),

                            new GradientStop(Colors.Transparent, 1)

                        }

                    }

                };



                var label = new Label

                {

                    TextColor = Colors.White,

                    FontSize = 20,

                    FontAttributes = FontAttributes.Bold,

                    Margin = new Thickness(15),

                    VerticalOptions = LayoutOptions.End

                };

                label.SetBinding(Label.TextProperty, "Title");



                grid.Children.Add(image);

                grid.Children.Add(gradient);

                grid.Children.Add(label);



                frame.Content = grid;

                var tapGesture = new TapGestureRecognizer();
                tapGesture.Tapped += async (s, e) =>
                {
                    if (frame.BindingContext is CarouselItem item)
                    {
                        DisplayAlert(item.Title, item.Description, "Selge");
                    }
                };
                frame.GestureRecognizers.Add(tapGesture);
                return frame;

            })

        };

        var indicatorView = new IndicatorView

        {

            IndicatorColor = Colors.LightGray,

            SelectedIndicatorColor = Colors.DarkSlateBlue,

            HorizontalOptions = LayoutOptions.Center,

            Margin = new Thickness(0, 10)

        };

        carouselView.IndicatorView = indicatorView;




        // Automaatne kerimine

        Device.StartTimer(TimeSpan.FromSeconds(4), () =>

        {

            if (items == null || items.Count == 0) return false;



            position = (position + 1) % items.Count;

            carouselView.Position = position;

            return true;

        });



        Content = new ScrollView

        {

            Content = new VerticalStackLayout

            {

                Padding = 20,

                Spacing = 20, // Jätab elementide vahele ilusa tühimiku

                Children =

                {

                    carouselView,

                    indicatorView

                    

                }

            }

        };

    }

}

